1913	/// Recalculate the initial size of the window based on the
1914	/// configuration and invoke the apprt `initial_size` action if
1915	/// necessary.
1916	fn recomputeInitialSize(
1917	    self: *Surface,
1918	) InitialSizeError!void {
1919	    // Both width and height must be set for this to work, as
1920	    // documented on the config options.
1921	    if (self.config.window_height <= 0 or
1922	        self.config.window_width <= 0) return;
1923	
1924	    const scale = self.rt_surface.getContentScale() catch
1925	        return error.ContentScaleUnavailable;
1926	    const height = @max(
1927	        self.config.window_height,
1928	        min_window_height_cells,
1929	    ) * self.size.cell.height;
1930	    const width = @max(
1931	        self.config.window_width,
1932	        min_window_width_cells,
1933	    ) * self.size.cell.width;
1934	    const width_f32: f32 = @floatFromInt(width);
1935	    const height_f32: f32 = @floatFromInt(height);
1936	
1937	    // The final values are affected by content scale and we need to
1938	    // account for the padding so we get the exact correct grid size.
1939	    const final_width: u32 =
1940	        @as(u32, @intFromFloat(@ceil(width_f32 / scale.x))) +
1941	        self.size.padding.left +
1942	        self.size.padding.right;
1943	    const final_height: u32 =
1944	        @as(u32, @intFromFloat(@ceil(height_f32 / scale.y))) +
1945	        self.size.padding.top +
1946	        self.size.padding.bottom;
1947	
1948	    _ = self.rt_app.performAction(
1949	        .{ .surface = self },
1950	        .initial_size,
1951	        .{ .width = final_width, .height = final_height },
1952	    ) catch return error.AppActionFailed;
1953	}
